					Corner = {
						Radius = Scope:UDim(0, Theme.CornerRadius.Full),
					},
					RingEnabled = true,
					RingColor = IndicatorColor,
				},
				Scope:Avatar {
					Image = "rbxthumb://type=AvatarHeadShot&id=144146784&w=150&h=150",
					Corner = {
						Radius = Scope:UDim(0, Theme.CornerRadius.Full),
