	local BackgroundColor3 = Util.Fallback(Props.BackgroundColor3, Theme.Colors.Base.Main)

	return Scope:Frame(Util.CombineProps(Props, {
		Name = script.Name,
		BackgroundColor3 = BackgroundColor3,
